// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c.owner()));
        vm.assume(caller != address(0));

        // Ensure at least one reward token is added by owner first
        address rewardToken = address(0x1234);
        vm.prank(c.owner());
        c.addReward(rewardToken);

        // Try to call addReward as non-owner
        vm.prank(caller);
        bool reverted = false;
        try c.addReward(address(0x5678)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}

